import {FISH_CONTRACTS,fishContractReason} from './fish-goals.js';import {fishPayment} from './fish-feed.js';
/** Bonus on already delivered/sold harvest weight; never resells or invents a fish lot. @param {import('./engine.js').State} state @param {import('./engine.js').Command} command @param {import('./fish-feed.js').FishTransaction} transact @returns {string|undefined} */
export function claimFishContract(state,command,transact){const g=state.fish,id=command.fishContract;if(!g||!id)return 'invalidFishCommand';const reason=fishContractReason(g,id);if(reason)return reason;const c=FISH_CONTRACTS.find(c=>c.id===id);if(!c)return 'invalidFishCommand';fishPayment(state,'fish.contract_reward',c.coins,'contract.'+id.split('.')[1],transact);g.contracts.push(id);if(!g.mission.completed.includes('contract'))g.mission.completed.push('contract');}
